class Solution {
public:
    int countTexts(std::string pressedKeys) {
        int MOD = 1e9 + 7;
        int n = pressedKeys.size();
        std::vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; ++i) {
            int max_k = (pressedKeys[i - 1] == '7' || pressedKeys[i - 1] == '9') ? 4 : 3;
            for (int k = 1; k <= max_k; ++k) {
                if (i - k >= 0 && pressedKeys[i - k] == pressedKeys[i - 1]) {
                    dp[i] = (dp[i] + dp[i - k]) % MOD;
                } else {
                    break;
                }
            }
        }
        return dp[n];
    }
};

class Solution {
    public int countTexts(String pressedKeys) {
        int MOD = 1_000_000_007;
        int n = pressedKeys.length();
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            char c = pressedKeys.charAt(i - 1);
            int maxK = (c == '7' || c == '9') ? 4 : 3;
            for (int k = 1; k <= maxK; k++) {
                if (i - k >= 0 && pressedKeys.charAt(i - k) == c) {
                    dp[i] = (dp[i] + dp[i - k]) % MOD;
                } else {
                    break;
                }
            }
        }
        return dp[n];
    }
}

var countTexts = function(pressedKeys) {
    const MOD = 1000000007;
    const n = pressedKeys.length;
    const dp = new Int32Array(n + 1);
    dp[0] = 1;
    for (let i = 1; i <= n; i++) {
        const c = pressedKeys[i - 1];
        const maxK = (c === '7' || c === '9') ? 4 : 3;
        for (let k = 1; k <= maxK; k++) {
            if (i - k >= 0 && pressedKeys[i - k] === c) {
                dp[i] = (dp[i] + dp[i - k]) % MOD;
            } else {
                break;
            }
        }
    }
    return dp[n];
};
